     'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}


def _valid(y, mo, d):
    try:
        date(y, mo, d)
        return 2000 <= y <= 2099
    except Exception:
        return False


def _try_swaps(y, mo, d):
    swaps = [('6', '0'), ('0', '6'), ('8', '3'), ('3', '8'),
             ('1', '7'), ('7', '1'), ('5', '6'), ('6', '5')]
    for field in ('mo', 'd'):
        s = str(mo if field == 'mo' else d)
        for a, b in swaps:
            if a in s:
                cand = int(s.replace(a, b, 1))
                nm, nd = (cand, d) if field == 'mo' else (mo, cand)
                if _valid(y, nm, nd):
                    return y, nm, nd
    return None


def extract_date(text):
    lines = text.splitlines()
