    date_iso = None
    for raw in variant_texts:
        date_iso = extract_date(raw)
        if date_iso:
            break
    return {'date': date_iso, 'total_amount': total_str}


def main():
    files = sorted(p.name for p in Path(IMG_DIR).iterdir()
                   if p.suffix.lower() in {'.jpg', '.jpeg', '.png', '.webp'})
    rows = []
    for name in files:
        res = extract_receipt_fields(os.path.join(IMG_DIR, name))
        print(name, res)
        rows.append((name, res['date'], res['total_amount']))

    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for fn, dt, amt in rows:
        r = ws.max_row + 1
        ws.cell(row=r, column=1, value=fn)
        ws.cell(row=r, column=2, value=dt if dt is not None else None)
        c = ws.cell(row=r, column=3, value=amt if amt is not None else None)
        if amt is not None:
            c.number_format = '@'
    wb.save(OUT_XLSX)
    print(f'Wrote {OUT_XLSX}')


